    if next_item_size > 0 && post_residual < next_item_size {
        score += 45.0 * (1.0 - progress);
    }

    // Heuristic for opening a new bin vs filling existing:
    // If we have very few bins open, we are more aggressive about packing tightly.
    // If the residual is very small, it's "fragile" space.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Only choose this if all existing bins result in very poor fits.
        // We add a dynamic bias that increases as we approach the end of the stream
        // to prevent fragmentation.
        score = 25.0 + (progress * 20.0);
    } else {
        // Bias towards bins that bring the residual closer to the global average.
        // This keeps bin utilization consistent.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the last chance to fit into a specific bin, reward it
