    // If post_residual is in the "danger zone" (1..19), heavily penalize unless it's a perfect fit.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // Harmonic alignment: prioritize residuals that are multiples of common item sizes.
    // Use modular arithmetic to favor configurations that leave space for lookahead items.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward cases where the residual perfectly accommodates the next item.
        if remainder == 0 {
            score -= 25.0;
        } else {
            // Penalize if the next item won't fit at all in this specific bin.
            if post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Dynamic thresholding: If we are near the end of the stream, prioritize bin consolidation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // New-bin handling: If bin_residual == bin_capacity, this is the "Open New Bin" candidate.
    // Only choose this if the current best existing bin is extremely poor (very high post_residual).
