    // Final adjustment based on fitting_bins_count: 
    // If this is the only bin that can fit the item, prioritize it to avoid forced new-bin usage.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
