pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space: smaller post_residual is usually better (Best Fit).
    // However, we penalize very small residuals (slivers) that are unlikely to accommodate future items.
    // A residual between 1 and 9 is often "dead space".
    let sliver_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Use lookahead: if next_item_size is large, we want a bin that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Encourage filling bins earlier in the stream, but allow flexibility as we near the end.
    // We normalize the influence of fitting_bins_count to prioritize bins that are "tight".
    let scarcity_factor = if fitting_bins_count == 1 { -10.0 } else { 0.0 };

    // Non-linear coupling: penalize high mean_residual to force consolidation.
    let consolidation_pressure = (mean_residual - post) * progress;

    let score = post + sliver_penalty + lookahead_penalty + scarcity_factor + consolidation_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating a "useless" residual:
    // If the post_residual is too small to fit the smallest expected items (e.g., < 10),
    // it creates dead space. If it is close to 0, it is excellent.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - (post_residual as f64 * 2.5);
    }

    // 2. Lookahead matching:
    // If we have a next_item, we want to prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: The bin can fit the next item perfectly.
            score -= 40.0;
        } else if post_residual > 0 {
            // Bad: The bin cannot fit the next item, forcing a new bin or a different fit.
            score += 15.0;
        }
    }

    // 3. New bin management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // it's the only option or the current open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        score += 30.0; 
        // If we have very few open bins, opening a new one is less costly.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Global state awareness:
    // If the bin's post-residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Urgency:
    // As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

