    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want to minimize the post-residual space (Best Fit), 
    // but we penalize very small residuals that create "dead space" (e.g., < 10 units).
    let mut score = post_residual as f64;

    if post_residual < 10 && post_residual > 0 {
