            score -= 15.0; // Reward bins that can hold the next item
        } else {
            score += 10.0; // Penalty for stranding the next item
        }
    }

    // Global state: If we have many open bins, we should be more aggressive in filling them.
    // As the stream progresses, prioritize closing bins to reduce open_bins_count.
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // Logic for new bins: Only open a new bin if the current fit is poor or 
    // if we are nearing the end of the stream and need to consolidate.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Mandatory new bin
        } else {
            // High threshold to avoid opening a new bin prematurely
            score = 45.0 + (mean_residual * 0.5);
            if progress > 0.9 {
                score += 50.0; // Extreme penalty for new bins at the very end
            }
        }
    }

    score
}
